// Full-corpus verification for item 21-I.3: replays every case of the
// pinned evidence corpus (validation/evidence/native/calendar-detection)
// through the transcribed machines via the shared replay layer
// (tests/calendar_detection_replay.h, the golden tables generated by
// tools/gen_calendar_detection_golden.py from that corpus) and
// additionally re-reads the raw corpus facts (cases.csv / inputs.csv and
// the per-case .txt journals) to cross-qualify the golden tables against
// the captured JVM lines: the case inventory and family counts, every
// threshold fed through the JVM (decimal in inputs.csv, re-parsed with
// strtod into raw bits), every machine result/mean token on the res lines,
// the det ATD best echo, the det FT Info bit patterns (already raw hex),
// the jt echoes and the pipeline tdspec lines. A corpus edit that moves
// any replayed fact therefore fails this sweep even before the unit
// replay runs.
#include <kalos/calendar_detection.hpp>

#include "../tests/calendar_detection_replay.h"

#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <iostream>
#include <iterator>
#include <sstream>
#include <stdexcept>
#include <string>
#include <unordered_map>
#include <vector>

namespace {

using kalos::replay::as_bits;
using kalos::replay::as_double;

int failures = 0;
int cross = 0;

void fail(const std::string& what) {
    std::cout << "FAIL " << what << std::endl;
    ++cross;
    ++failures;
}

void check_cross(bool ok, const std::string& what) {
    ++cross;
    if (!ok) fail(what);
}

std::vector<std::string> tokens(const std::string& s) {
    std::vector<std::string> out;
    std::istringstream in(s);
    std::string t;
    while (in >> t) out.push_back(t);
    return out;
}

// One "id","rest" csv row (inputs.csv: rest = the case header line;
// cases.csv: rest = "note",lines - only the id and the quoted column 2
// are ever consumed).
struct CsvRow {
    std::string id;
    std::string second;
};

std::vector<CsvRow> read_csv2(const std::string& path) {
    std::ifstream in(path);
    if (!in) throw std::runtime_error("cannot open " + path);
    std::vector<CsvRow> out;
    std::string line;
    bool header = true;
    while (std::getline(in, line)) {
        if (line.empty()) continue;
        if (header) {
            header = false;
            continue;  // "id",...
        }
        if (line.size() < 3 || line[0] != '"') {
            fail("corpus row without quoted id: " + path + ": " + line);
            continue;
        }
        CsvRow r;
        const std::size_t q1 = line.find("\",\"");
        if (q1 == std::string::npos) {
            fail("corpus row without second column: " + path + ": " + line);
            continue;
        }
        r.id = line.substr(1, q1 - 1);
        const std::size_t q2 = line.rfind('"');
        r.second = line.substr(q1 + 3, q2 - (q1 + 3));
        out.push_back(r);
    }
    return out;
}

std::uint64_t decbits(const std::string& s) {
    return as_bits(std::strtod(s.c_str(), nullptr));
}

std::string hexbits(std::uint64_t b) {
    char buf[24];
    std::snprintf(buf, sizeof(buf), "%016llx",
                  static_cast<unsigned long long>(b));
    return buf;
}

std::string read_file(const std::string& path) {
    std::ifstream in(path);
    if (!in) throw std::runtime_error("cannot open " + path);
    std::ostringstream ss;
    ss << in.rdbuf();
    return ss.str();
}

std::vector<std::string> lines_of(const std::string& text) {
    std::vector<std::string> out;
    std::istringstream in(text);
    std::string l;
    while (std::getline(in, l)) out.push_back(l);
    return out;
}

// The result code of a `res <id> <kind> <Result> ...` journal line,
// -1 when the token is unknown (Unprocessed only exists for the DS
// family's `res <id> default Unprocessed ...` line).
int res_code(const std::string& tok) {
    if (tok == "Unchanged") return 0;
    if (tok == "Changed") return 1;
    if (tok == "Failed") return 2;
    if (tok == "Unprocessed") return 3;
    return -1;
}

const std::string kFamilyPrefix[] = {"cm_", "ta_", "ft_", "sa_", "fs_",
                                     "ds_", "jt_", "pt_", "px_"};
const char* kFamilyName[] = {"CM", "TA", "FT", "SA", "FS", "DS",
                             "JT", "PT", "PX"};

int family_of(const std::string& id) {
    for (int f = 0; f < 9; ++f)
        if (id.rfind(kFamilyPrefix[f], 0) == 0) return f;
    return -1;
}

std::string find_line_with(const std::vector<std::string>& lines,
                           const std::string& key) {
    for (const auto& l : lines) {
        const std::vector<std::string> t = tokens(l);
        if (t.size() > 1 && t[0] == key) return l;
    }
    return "";
}

// The k=v map of the first `... det FT ...` journal line (hex bit
// patterns), empty when the line is absent.
std::unordered_map<std::string, std::string> det_ft(const std::string& txt) {
    std::unordered_map<std::string, std::string> out;
    for (const auto& l : lines_of(txt)) {
        if (l.find("det FT ") == std::string::npos) continue;
        for (const auto& tok : tokens(l)) {
            const std::size_t eq = tok.find('=');
            if (eq != std::string::npos)
                out[tok.substr(0, eq)] = tok.substr(eq + 1);
        }
        break;
    }
    return out;
}

void cross_qualify(const std::string& corpus) {
    // ---- inventory: cases.csv vs. the golden tables -------------------
    const auto cases = read_csv2(corpus + "/cases.csv");
    const auto inputs = read_csv2(corpus + "/inputs.csv");
    std::unordered_map<std::string, std::string> hdr;
    for (const auto& r : inputs) hdr[r.id] = r.second;
    check_cross(cases.size() == 43, "cases.csv rows " +
                                        std::to_string(cases.size()) + " != 43");
    check_cross(inputs.size() == cases.size(),
                "inputs.csv rows != cases.csv rows");
    const std::size_t want_n[9] = {
        std::size(kalos::test::kCdCmp),   7,
        std::size(kalos::test::kCdFtest), 7,
        std::size(kalos::test::kCdFastStep),
        std::size(kalos::test::kCdDefaultStep),
        std::size(kalos::test::kCdJoint), 4, 3};
    // The TA/SA and PT/PX families share one table each: split by prefix.
    std::size_t ta = 0, sa = 0, pt = 0, px = 0;
    for (const auto& c : kalos::test::kCdLadder)
        (c.sa == 0 ? ta : sa) += 1;
    for (const auto& c : kalos::test::kCdPipe)
        (c.px == 0 ? pt : px) += 1;
    check_cross(want_n[1] == ta && ta == 7, "golden TA count");
    check_cross(want_n[3] == sa && sa == 7, "golden SA count");
    check_cross(want_n[7] == pt && pt == 4, "golden PT count");
    check_cross(want_n[8] == px && px == 3, "golden PX count");
    int fam_count[9] = {0};
    for (const auto& r : cases) {
        const int f = family_of(r.id);
        check_cross(f >= 0, "case id without family: " + r.id);
        if (f >= 0) ++fam_count[f];
        check_cross(hdr.count(r.id) == 1, "case without inputs.csv row: " + r.id);
    }
    for (int f = 0; f < 9; ++f)
        check_cross(fam_count[f] == want_n[f],
                    std::string("family ") + kFamilyName[f] +
                        " count " + std::to_string(fam_count[f]) + " != " +
                        std::to_string(want_n[f]));

    // ---- thresholds: decimal inputs.csv re-parsed into raw bits -------
    for (const auto& c : kalos::test::kCdCmp) {
        const auto t = tokens(hdr[c.id]);
        check_cross(t.size() > 9 && decbits(t[8]) == c.pmodel,
                    std::string(c.id) + ": pmodel bits");
        check_cross(t.size() > 9 && decbits(t[9]) == c.pconstraint,
                    std::string(c.id) + ": pconstraint bits");
    }
    for (const auto& c : kalos::test::kCdLadder) {
        const auto t = tokens(hdr[c.id]);
        const char* sel = c.selector == 0 ? "aicc"
                                          : (c.selector == 1 ? "bic" : "wald");
        check_cross(t.size() > 8 && t[6] == sel,
                    std::string(c.id) + ": selector");
        check_cross(t.size() > 8 && decbits(t[7]) == c.pmodel,
                    std::string(c.id) + ": pmodel bits");
        check_cross(t.size() > 8 && decbits(t[8]) == c.pconstraint,
                    std::string(c.id) + ": pconstraint bits");
        if (c.sa == 1) {
            check_cross(t.size() > 10 && decbits(t[10]) == c.tlp,
                        std::string(c.id) + ": tlp bits");
        } else {
            check_cross(c.tlp == as_bits(2.0),
                        std::string(c.id) + ": TA tlp constant 2.0");
        }
    }
    for (const auto& c : kalos::test::kCdFtest) {
        const auto t = tokens(hdr[c.id]);
        check_cross(t.size() > 9 && decbits(t[9]) == c.fpvalue,
                    std::string(c.id) + ": fpvalue bits");
        check_cross(t.size() > 8 && ((t[6] == "y") == (c.has_easter != 0)) &&
                        ((t[7] == "y") == (c.testmean != 0)) &&
                        ((t[8] == "y") == (c.adjust != 0)),
                    std::string(c.id) + ": easter/mean/adjust flags");
    }
    for (const auto& c : kalos::test::kCdFastStep) {
        const auto t = tokens(hdr[c.id]);
        check_cross(t.size() > 7 && decbits(t[6]) == c.tmean &&
                        decbits(t[7]) == c.tvar,
                    std::string(c.id) + ": tmean/tvar bits");
        check_cross(t.size() > 8 && (t[8] == "y") == (c.testmean != 0),
                    std::string(c.id) + ": testmean flag");
    }
    for (const auto& c : kalos::test::kCdDefaultStep) {
        const auto t = tokens(hdr[c.id]);
        check_cross(t.size() > 6 && decbits(t[6]) == c.tmean,
                    std::string(c.id) + ": tmean bits");
        check_cross(t.size() > 9 && (t[7] == "y") == (c.testmean != 0) &&
                        (t[9] == "y") == (c.join != 0),
                    std::string(c.id) + ": testmean/join flags");
    }
    for (const auto& c : kalos::test::kCdJoint) {
        const auto t = tokens(hdr[c.id]);
        check_cross(t.size() > 8 && std::atoi(t[6].c_str()) == c.pos &&
                        std::atoi(t[7].c_str()) == c.q &&
                        std::atoi(t[8].c_str()) == c.k,
                    std::string(c.id) + ": pos/q/k");
    }

    // ---- journals: res / det ATD / det FT / jt / tdspec echoes --------
    for (const auto& c : kalos::test::kCdLadder) {
        const std::string txt = read_file(corpus + "/" + c.id + ".txt");
        const auto lines = lines_of(txt);
        const std::string res = find_line_with(lines, "res");
        const auto t = tokens(res);
        check_cross(t.size() > 3 && res_code(t[3]) == c.result,
                    std::string(c.id) + ": res result");
        const std::size_t mp = res.find(" mean ");
        check_cross(mp != std::string::npos &&
                    (res.compare(mp + 6, 1, "1") == 0) == (c.mean_after != 0),
                    std::string(c.id) + ": res mean");
        int raw_best = -999;
        for (const auto& l : lines)
            for (std::size_t p = 0;
                 (p = l.find("best=", p)) != std::string::npos; p += 5)
                if (p == 0 || l[p - 1] == ' ')
                    raw_best = std::atoi(l.c_str() + p + 5);
        check_cross(raw_best == c.det_atd_best,
                    std::string(c.id) + ": det ATD best");
    }
    for (const auto& c : kalos::test::kCdFtest) {
        const std::string txt = read_file(corpus + "/" + c.id + ".txt");
        const std::string res = find_line_with(lines_of(txt), "res");
        const auto t = tokens(res);
        check_cross(t.size() > 3 && res_code(t[3]) == c.result,
                    std::string(c.id) + ": res result");
        const auto info = det_ft(txt);
        if (c.info_seen == 0) {
            check_cross(info.empty(), std::string(c.id) + ": unexpected Info");
            continue;
        }
        check_cross(!info.empty(), std::string(c.id) + ": missing det FT");
        const std::pair<const char*, std::uint64_t> want[] = {
            {"ss0", c.ss0},      {"ss1", c.ss1},     {"ss6", c.ss6},
            {"ssmc1", c.ssmc1},  {"ssmc6", c.ssmc6}, {"pftd1", c.pftd1},
            {"pftd6", c.pftd6}};
        for (const auto& w : want) {
            const auto it = info.find(w.first);
            check_cross(it != info.end() && it->second == hexbits(w.second),
                        std::string(c.id) + ": det FT " + w.first);
        }
        const auto nhp = info.find("nhp");
        check_cross(nhp != info.end() &&
                        std::atoi(nhp->second.c_str()) == c.info_none.nhp,
                    std::string(c.id) + ": det FT nhp");
    }
    for (const auto& c : kalos::test::kCdFastStep) {
        const std::string txt = read_file(corpus + "/" + c.id + ".txt");
        const std::string res = find_line_with(lines_of(txt), "res");
        const auto t = tokens(res);
        check_cross(t.size() > 3 && res_code(t[3]) == c.result,
                    std::string(c.id) + ": res result");
        const std::size_t ep = res.find(" est ");
        check_cross(ep != std::string::npos &&
                    (res.compare(ep + 5, 3, "set") == 0) == (c.est_set != 0),
                    std::string(c.id) + ": res est");
    }
    for (const auto& c : kalos::test::kCdDefaultStep) {
        const std::string txt = read_file(corpus + "/" + c.id + ".txt");
        const std::string res = find_line_with(lines_of(txt), "res");
        const auto t = tokens(res);
        check_cross(t.size() > 3 && res_code(t[3]) == c.result,
                    std::string(c.id) + ": res result");
        const std::string jt = find_line_with(lines_of(txt), "jt");
        if (c.jt_q == 0) {
            check_cross(jt.empty(), std::string(c.id) + ": unexpected jt");
            continue;
        }
        const auto t2 = tokens(jt);  // jt id q Q df D value HEX pvalue HEX
        check_cross(t2.size() == 10 && std::atoi(t2[3].c_str()) == c.jt_q &&
                        std::atoi(t2[5].c_str()) == c.jt_df &&
                        t2[7] == hexbits(c.jt_value) &&
                        t2[9] == hexbits(c.jt_pvalue),
                    std::string(c.id) + ": jt echo");
    }
    for (const auto& c : kalos::test::kCdJoint) {
        const std::string txt = read_file(corpus + "/" + c.id + ".txt");
        const std::string jt = find_line_with(lines_of(txt), "jt");
        const auto t = tokens(jt);  // jt id pos P q Q k K value HEX pvalue HEX
        check_cross(t.size() == 12 && std::atoi(t[3].c_str()) == c.pos &&
                        std::atoi(t[5].c_str()) == c.q &&
                        std::atoi(t[7].c_str()) == c.k &&
                        t[9] == hexbits(c.value) &&
                        t[11] == hexbits(c.pvalue),
                    std::string(c.id) + ": jt echo");
    }
    for (const auto& c : kalos::test::kCdPipe) {
        const std::string txt = read_file(corpus + "/" + c.id + ".txt");
        const std::string spec =
            find_line_with(lines_of(txt), c.px == 0 ? "tdspec" : "x13tdspec");
        check_cross(spec == c.tdspec, std::string(c.id) + ": tdspec line");
    }
}

}  // namespace

int main(int argc, char** argv) {
    const std::string corpus =
        argc > 1 ? argv[1] : "validation/evidence/native/calendar-detection";
    try {
        cross_qualify(corpus);
    } catch (const std::exception& ex) {
        std::cout << "FAIL corpus: " << ex.what() << std::endl;
        return 1;
    }
    kalos::replay::Reporter rep;
    kalos::replay::replay_cmp(rep);
    kalos::replay::replay_ladder(rep);
    kalos::replay::replay_ftest(rep);
    kalos::replay::replay_fast_step(rep);
    kalos::replay::replay_default_step(rep);
    kalos::replay::replay_joint(rep);
    kalos::replay::replay_pipe(rep);
    std::cout << "verify_calendar_detection: "
              << std::size(kalos::test::kCdCmp) << " cmp, "
              << std::size(kalos::test::kCdLadder) << " ladder, "
              << std::size(kalos::test::kCdFtest) << " ftest, "
              << std::size(kalos::test::kCdFastStep) << " fast, "
              << std::size(kalos::test::kCdDefaultStep) << " default, "
              << std::size(kalos::test::kCdJoint) << " joint, "
              << std::size(kalos::test::kCdPipe) << " pipe cases, "
              << rep.checks << " replay checks, " << cross
              << " corpus cross-checks, " << failures << " failures"
              << std::endl;
    return failures == 0 ? 0 : 1;
}
